    answer = [-1] * (m + 1)

    # reachable: set of banana counts reachable at current step
    reachable = {0}

    for step, (t, x, y) in enumerate(operations, 1):
        new_reachable = set(reachable)

        for k in reachable:
            if t == 1:
                # Type 1: k := ceil(k + x) applied a_i times, where 0 <= a_i <= y
                # Apply operation multiple times
                k_temp = k
                for _ in range(y):
                    k_temp = ceil(k_temp + x)
                    if k_temp > m:
                        break
                    if k_temp not in new_reachable and k_temp <= m:
                        new_reachable.add(k_temp)
            else:
                # Type 2: k := ceil(k * x) applied a_i times, where 0 <= a_i <= y
                k_temp = k
                for _ in range(y):
                    k_temp = ceil(k_temp * x)
                    if k_temp > m:
                        break
                    if k_temp not in new_reachable and k_temp <= m:
                        new_reachable.add(k_temp)

        # Update all newly discovered answers at this step
        for val in new_reachable:
            if val > 0 and answer[val] == -1:
                answer[val] = step

        reachable = new_reachable

        if not reachable:
            reachable = {0}

