    # Use segmented sieve

    limit = r
    if limit < 2:
        return '0\n'

    # Sieve of Eratosthenes up to sqrt(r) for base primes
    sqrt_r = int(limit**0.5) + 1
    base_primes = []
    is_prime_base = [True] * (sqrt_r + 1)
    is_prime_base[0] = is_prime_base[1] = False

    for i in range(2, sqrt_r + 1):
        if is_prime_base[i]:
            base_primes.append(i)
            for j in range(i*i, sqrt_r + 1, i):
                is_prime_base[j] = False

    # Segmented sieve for range [l, r]
    def sieve_segmented(start, end):
        if start < 2:
            start = 2
        size = end - start + 1
        is_prime = [True] * size

        for p in base_primes:
            # Find first multiple of p >= start
            first = (start + p - 1) // p * p
            if first < p * p:
                first = p * p

            # Mark multiples
            for i in range(first, end + 1, p):
                is_prime[i - start] = False

        return is_prime

    is_prime = sieve_segmented(l, r)

    count = 0
    for i in range(len(is_prime)):
        num = l + i
        if is_prime[i]:
            if num == 2 or num % 4 == 1:
                count += 1

    return f'{count}\n'

