from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0

    n = int(lines[idx])
    idx += 1

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u, v = map(int, lines[idx].split())
        idx += 1
        adj[u].append(v)
        adj[v].append(u)

    k = int(lines[idx])
    idx += 1

    bob_positions = set(map(int, lines[idx].split()))

    # For each vertex, find minimum distance to any Bob chip
    results = []

    for start_node in range(1, n + 1):
        if start_node in bob_positions:
            results.append(0)
        else:
            # BFS to find minimum distance to any Bob chip
            dist = {node: float('inf') for node in range(1, n + 1)}
            dist[start_node] = 0

            queue = deque([start_node])

            while queue:
                curr = queue.popleft()

                if curr in bob_positions:
                    results.append(0)
                    break

                for neighbor in adj[curr]:
                    if neighbor not in dist:
                        dist[neighbor] = dist[curr] + 1
                        queue.append(neighbor)

            if len(results) > 0 and dist[start_node] != 0:
                # Find minimum distance to any Bob chip
                min_dist = float('inf')
                for node in range(1, n + 1):
                    if node in bob_positions:
                        if dist[node] < min_dist:
                            min_dist = dist[node]

                if min_dist == float('inf'):
                    results.append(0)
                else:
                    results.append(min_dist + 1)

    return '\n' + ' '.join(map(str, results)) + '\n'


