    def get_lucky_numbers(limit):
        lucky = []
        def dfs(current):
            if current > limit:
                return
            if current != 0:
                lucky.append(current)
            if current * 10 + 4 <= limit:
                dfs(current * 10 + 4)
            if current * 10 + 7 <= limit:
                dfs(current * 10 + 7)
        dfs(0)
        return sorted(set(lucky))

    lucky_numbers = get_lucky_numbers(n)

    # Build graph and find connected components
    graph = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        line = lines[i]
        u, v = map(int, line.split())
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * (n + 1)
    component_sizes = []

    def bfs(start):
        size = 0
        queue = [start]
        visited[start] = True
        while queue:
            node = queue.pop(0)
            size += 1
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)
        return size

    for i in range(1, n + 1):
        if not visited[i]:
            component_sizes.append(bfs(i))

    if len(component_sizes) == 0:
        return "-1"

    # DP to find minimum components needed for each lucky sum
    # dp[s] = minimum number of components whose sizes sum to s
    dp = {}
    dp[0] = 0

    for size in component_sizes:
        updated = set()
        for s in list(dp.keys()):
            new_s = s + size
            if new_s in lucky_numbers:
                new_count = dp[s] + 1
                if new_s not in dp or dp[new_s] > new_count:
                    updated.add(new_s)
            # Continue accumulating
            if new_s <= n and new_s not in dp:
                updated.add(new_s)
        for s in updated:
            if s not in dp or dp[s] > dp.get(s, float('inf')):
                dp[s] = dp.get(s, float('inf')) + 0 if s == 0 else (dp.get(s, float('inf')) + 0)

    # Correct DP approach - track min components for each sum
    dp = {0: 0}
    for size in component_sizes:
        new_dp = dp.copy()
        for s, count in dp.items():
            new_s = s + size
            if new_s in lucky_numbers:
                new_count = count + 1
                if new_s not in dp or dp[new_s] > new_count:
                    new_dp[new_s] = new_count
            dp = new_dp

    # Find minimum roads (components - 1)
    min_components = float('inf')
    for s in lucky_numbers:
        if s in dp:
            min_components = min(min_components, dp[s])

    if min_components == float('inf'):
        return "-1"

    return str(min_components - 1) + "\n"

