def solution(input_str):
    data = input_str.strip().split('\n')
    n, m = map(int, data[0].split())

    # If only MST edges exist, nothing to output
    if m == n - 1:
        return ""

    # Parse edges: (weight, u, v, original_index)
    edges = []
    for i in range(m):
        parts = list(map(int, data[i + 1].split()))
        edges.append((parts[2], parts[0] - 1, parts[1] - 1, i))

    # Sort by weight for Kruskal's
    edges.sort()

    # Union-Find
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        curr = x
        while curr != root:
            next_curr = parent[curr]
            parent[curr] = root
            curr = next_curr
        return root

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return False
        if rank[px] < rank[py]:
            px, py = py, px
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1
        return True

    # Build MST
    mst_adj = [[] for _ in range(n)]
    in_mst = [False] * m

    for w, u, v, idx in edges:
        if union(u, v):
            mst_adj[u].append((v, w))
            mst_adj[v].append((u, w))
            in_mst[idx] = True

    # Precompute LCA and path max using DFS
    parent = [0] * n
    depth = [0] * n
    edge_to_parent = [0] * n
    up = [[-1] * n for _ in range(18)]

    stack = [0]
    parent[0] = -1

    while stack:
        u = stack.pop()
        for v, w in mst_adj[u]:
            if v != parent[u]:
                parent[v] = u
                depth[v] = depth[u] + 1
                edge_to_parent[v] = w
                stack.append(v)

    up[0] = parent[:]

    for j in range(1, 18):
        for i in range(n):
            if up[j - 1][i] != -1:
                up[j][i] = up[j - 1][up[j - 1][i]]

    def query(u, v):
        if depth[u] < depth[v]:
            u, v = v, u

        res = 0
        diff = depth[u] - depth[v]
        for j in range(18):
            if diff & (1 << j):
                w = edge_to_parent[up[j][u]]
                res = max(res, w)
                u = up[j][u]

        if u == v:
            return res

        for j in range(17, -1, -1):
            if up[j][u] != up[j][v]:
                w1 = edge_to_parent[up[j][u]]
                w2 = edge_to_parent[up[j][v]]
                res = max(res, w1, w2)
                u = up[j][u]
                v = up[j][v]

        w1 = edge_to_parent[u]
        w2 = edge_to_parent[v]
        res = max(res, w1, w2)

        return res

    # Collect results in original order
    output = []
    for w, u, v, idx in edges:
        if not in_mst[idx]:
            output.append(str(query(u, v)))

    return '\n'.join(output)

