    lines = input_str.strip().split('\n')
    n = int(lines[0])

    costs = []
    for i in range(n):
        line = lines[1 + i].split()
        costs.append([int(x) for x in line])

    # Build preferences for each city (sorted by cost, lower is better)
    preferences = []
    for i in range(n):
        pref_list = [(j, costs[i][j]) for j in range(n) if i != j]
        pref_list.sort(key=lambda x: x[1])
        preferences.append([p[0] for p in pref_list])

    # Gale-Shapley for stable roommates
    tentative_match = [-1] * n
    proposal_ptr = [0] * n
    proposing = list(range(n))

    while proposing:
        u = proposing[-1]

        # Check if u is still unmatched
        if tentative_match[u] != -1:
            proposing.pop()
            continue

        # Try next preference
        if proposal_ptr[u] < n:
            v = preferences[u][proposal_ptr[u]]
            proposal_ptr[u] += 1

            if tentative_match[v] == -1:
                tentative_match[v] = u
                tentative_match[u] = v
                proposing.pop()
            else:
                prev = tentative_match[v]
                # V accepts u if costs[v][u] < costs[v][prev]
                if costs[v][u] < costs[v][prev]:
                    tentative_match[v] = u
                    tentative_match[u] = v
                    # prev is now rejected
                    tentative_match[prev] = -1
                    proposing.append(prev)
                else:
                    # V rejects u, u stays unmatched for now
                    proposing.pop()
        else:
            # u has exhausted all preferences
            proposing.pop()

    # If perfect matching not found, no stable matching exists
    if any(m == -1 for m in tentative_match):
        return "-1\n"

    # Verify stability - check for blocking pairs
    partner = [-1] * n
    for i in range(n):
        if tentative_match[i] != -1:
            partner[i] = tentative_match[i]
            partner[tentative_match[i]] = i

    stable = True
    for i in range(n):
        for j in range(i + 1, n):
            # Skip if already paired
            if partner[i] == j or partner[j] == i:
                continue

            # Check if (i, j) is a blocking pair
            current_cost_i = costs[i][partner[i]]
            current_cost_j = costs[j][partner[j]]
            proposed_cost_i = costs[i][j]
            proposed_cost_j = costs[j][i]

            # Blocking pair: both would prefer each other
            if proposed_cost_i < current_cost_i and proposed_cost_j < current_cost_j:
                stable = False
                break

        if not stable:
            break

    if stable:
        output = []
        for i in range(n):
            output.append(str(tentative_match[i]))
        return "\n".join(output) + "\n"
    else:
        return "-1\n"

