def cross_product(o, a, b):
    """
    Computes the cross product of vectors OA and OB.
    Returns positive if O->A->B is counter-clockwise, negative if clockwise, 0 if collinear.
    """
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])


def orientation(p, q, r):
    """
    Returns the orientation of the triplet (p, q, r).
    0 -> Collinear, 1 -> Clockwise, 2 -> Counterclockwise
    """
    val = cross_product(p, q, r)
    if val == 0:
        return 0
    return 1 if val > 0 else 2


def on_segment(p, q, r):
    """
    Checks if point q lies on segment pr (assuming collinearity).
    """
    return min(p[0], r[0]) <= q[0] <= max(p[0], r[0]) and min(p[1], r[1]) <= q[1] <= max(p[1], r[1])


def do_intersect(p1, q1, p2, q2):
    """
    Checks if segment p1q1 intersects with segment p2q2.
    Returns True if they intersect (excluding endpoints).
    """
    o1 = orientation(p2, q2, p1)
    o2 = orientation(p2, q2, q1)
    o3 = orientation(p1, q1, p2)
    o4 = orientation(p1, q1, q2)

    # General case
    if o1 != o2 and o3 != o4:
        return True

    # Special cases - collinear points
    if o1 == 0 and on_segment(p2, p1, q2):
        return True
    if o2 == 0 and on_segment(p2, q1, q2):
        return True
    if o3 == 0 and on_segment(p1, p2, q1):
