    if o4 == 0 and on_segment(p1, q2, q1):
        return True

    return False


def is_valid_diagonal(n, vertices, i, j):
    """
    Checks if diagonal (i, j) is valid in the polygon.
    A diagonal is valid if:
    1. i and j are not consecutive vertices (except the closing edge)
    2. The diagonal doesn't intersect any other polygon edges
    3. The polygon is simple (no self-intersections)
    """
    if i == j:
        return False

    # Check if indices are consecutive (skip polygon edges)
    if abs(i - j) == 1:
        return True  # These are edges, valid by definition
    if i == 0 and j == n - 1:
        return True  # Closing edge

    # This diagonal connects non-consecutive vertices
    # Check if it intersects any other edges of the polygon
    for k in range(n):
        next_k = (k + 1) % n
        if k == i or k == j or next_k == i or next_k == j:
            continue

        # Skip if this edge is the same as our diagonal
        edge_start = k
        edge_end = next_k

        if (edge_start == i and edge_end == j) or (edge_start == j and edge_end == i):
            continue

        # Check intersection
        if k == i or k == j or next_k == i or next_k == j:
            continue

        if do_intersect(vertices[i], vertices[j], vertices[k], vertices[next_k]):
            return False

    return True


def count_triangulations(n, vertices):
    """
    Uses dynamic programming to count triangulations of a simple polygon.
    dp[i][j] = number of ways to triangulate the subpolygon from vertex i to vertex j
    """
    dp = {}

    def count_subpolygon(i, j):
        """Count ways to triangulate subpolygon from vertex i to vertex j (in order)."""
        if i + 1 == j:
            return 1  # Just an edge, no triangulation needed

        if (i, j) in dp:
            return dp[(i, j)]

        result = 0
        # Try all possible vertices k that can form a triangle with i and j
        for k in range(i + 1, j):
            # Check if triangle (i, j, k) is valid
            if is_valid_diagonal(n, vertices, i, k) and is_valid_diagonal(n, vertices, k, j):
                result = (result + count_subpolygon(i, k) * count_subpolygon(k, j)) % MOD

        dp[(i, j)] = result
        return result

    # Start counting from vertex 0 to vertex n-1
    if n == 3:
        return 1

    result = count_subpolygon(0, n - 1)
    return result


