            break

    # This is a fixed-point computation that needs to handle wrapping
    # For simple polygon triangulation, we anchor at vertex 0

    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        dp[i][i] = 1

    for length in range(2, n):
        for i in range(n):
            j = (i + length) % n  # Handle wraparound

            if j < i:
                continue

            # We're computing dp[i][j] which represents triangulation of polygon
            # from vertex i to vertex j going forward along the boundary

            if length == 2:
                # Triangle (i, i+1, j) - just one triangle
                dp[i][j] = 1
            else:
