def solution(input_str):
    """
    Solve the poker sequence problem.

    Args:
        input_str: String containing n, k on first line and sequence s on second line

    Returns:
        Valid sequence string or "NO"
    """
    input_str = input_str.strip()
    lines = input_str.split('\n')
    n, k = map(int, lines[0].split())
    s = lines[1]

    # If no '?' characters, just validate the existing sequence
    if '?' not in s:
        diff = 0
        for c in s:
            if c == 'W':
                diff += 1
            elif c == 'L':
                diff -= 1
            # D doesn't affect difference

        # Check if final |diff| == k and no intermediate |diff| == k
        for i in range(n):
            if s[i] not in ('D', '?'):
                if s[i] == 'W':
                    diff += 1
                else:
                    diff -= 1
                if abs(diff) == k and i < n - 1:
                    return "NO"
        if abs(diff) == k:
            return s
        else:
            return "NO"

    # DP approach: dp[diff] = list of (previous_diff, choice) paths
    # Since we need to reconstruct, store actual paths
    dp = {0: [None]}  # at position -1 (before starting), diff is 0

    for i in range(n):
        new_dp = {}
        char = s[i]

        options = []
        if char == '?':
            options = ['W', 'L', 'D']
        else:
            options = [char]

        for prev_diff, history in dp.items():
            for choice in options:
                change = {'W': 1, 'L': -1, 'D': 0}[choice]
                new_diff = prev_diff + change

                # Check constraint: before last hand, |diff| != k
                if i < n - 1:
                    if abs(new_diff) == k:
                        continue

                if new_diff not in new_dp:
                    new_dp[new_diff] = []
                new_dp[new_diff].append((prev_diff, choice, history))

        dp = new_dp

        if not dp:
            return "NO"

    # Check final states
    final_valid = []
    for diff, history in dp.items():
        if abs(diff) == k:
            final_valid.append(history)

    if not final_valid:
        return "NO"

    # Reconstruct and return the first valid sequence
    result = final_valid[0][0]  # This is a string with characters
    return result

