        idx += n

        directions = [list(lines[idx + i]) for i in range(n)]
        idx += n

        # Build graph: each cell points to exactly one next cell
        next_cell = {}
        for i in range(n):
            for j in range(m):
                d = directions[i][j]
                if d == 'U':
                    next_cell[(i, j)] = (i - 1, j)
                elif d == 'D':
                    next_cell[(i, j)] = (i + 1, j)
                elif d == 'L':
                    next_cell[(i, j)] = (i, j - 1)
                elif d == 'R':
                    next_cell[(i, j)] = (i, j + 1)

        # Find cycle ID and position in cycle for each node
        cycle_id = {}  # u -> cid
        pos_in_cycle = {}  # u -> position in cycle (0 to cycle_len-1)

        # Compute (cid, pos_in_cycle) for each cell
        for start in next_cell:
            path = []
            curr = start
            seen = set()

            # Follow the path until we find a cycle
            while curr not in seen:
                if curr not in next_cell:
                    break
                seen.add(curr)
                path.append(curr)
                curr = next_cell[curr]

            # curr is in path, so we found a cycle
            if curr in path:
                cycle_start_idx = path.index(curr)
                cycle_nodes = path[cycle_start_idx:]
                cycle_len = len(cycle_nodes)

                # Assign this cycle a unique ID
                cycle_id_val = sum(1 for v in cycle_id.values())

                # Mark all nodes in cycle
                for idx_cycle, node in enumerate(cycle_nodes):
                    cycle_id[node] = cycle_id_val
                    pos_in_cycle[node] = idx_cycle

        # Group cells by their cycle (cid, position_in_cycle)
        groups = {}
        for start in next_cell:
            if start in cycle_id and start in pos_in_cycle:
                key = (cycle_id[start], pos_in_cycle[start])
                if key not in groups:
                    groups[key] = {'count': 0, 'black': 0, 'cells': []}
                groups[key]['count'] += 1
                groups[key]['cells'].append(start)

        # Calculate answer
        max_robots = len(groups)
        max_black = 0
        for key, info in groups.items():
            max_black += info['black']

        # Now count characters
        for i in range(n):
            for j in range(m):
                key = (cycle_id[(i, j)], pos_in_cycle[(i, j)])
                if key not in groups:
                    groups[key] = {'black': 0, 'count': 0}
                if colors[i][j] == '0':
                    groups[key]['black'] += 1
                if (i, j) in next_cell:
                    groups[key]['count'] += 1

        max_black = sum(group['black'] for group in groups.values())
        max_robots = len(groups)

        results.append(f"{max_robots} {max_black}")

    return '\n'.join(results)

