    class SegmentTree:
        def __init__(self, n):
            self.n = n
            self.tree = [float('inf')] * (4 * n)

        def update(self, idx, val):
            self._update(0, 0, self.n - 1, idx, val)

        def _update(self, node, l, r, idx, val):
            if l == r:
                self.tree[node] = val
                return
            mid = (l + r) // 2
            if idx <= mid:
                self._update(2 * node + 1, l, mid, idx, val)
            else:
                self._update(2 * node + 2, mid + 1, r, idx, val)
            self.tree[node] = min(self.tree[2 * node + 1], 
                                  self.tree[2 * node + 2])

        def query(self, l, r):
            if l > r:
                return 0
            return self._query(0, 0, self.n - 1, l, r)

        def _query(self, node, l, r, ql, qr):
            if ql > r or qr < l:
                return float('inf')
            if ql <= l and qr >= r:
                return self.tree[node]
            mid = (l + r) // 2
            return min(self._query(2 * node + 1, l, mid, ql, qr),
                      self._query(2 * node + 2, mid + 1, r, ql, qr))

    def compute_min_cuts(n, w, x, k):
        if n == 0:
            return 0

        T = w - k  # Constraint: max - min <= T

        if T >= n:
            return 0

        dp = [0] * n
        seg_tree = SegmentTree(n)
        seg_tree.update(0, 0)

        from collections import deque
        min_q = deque()
        max_q = deque()

        left = 0

        for i in range(n):
            while min_q and x[min_q[-1]] >= x[i]:
                min_q.pop()
            min_q.append(i)
            while max_q and x[max_q[-1]] <= x[i]:
                max_q.pop()
            max_q.append(i)

            while x[max_q[0]] - x[min_q[0]] > T:
                left += 1
                while min_q[0] < left:
                    min_q.popleft()
                while max_q[0] < left:
                    max_q.popleft()

            if left == 0:
                dp[i] = 0
            else:
                dp[i] = seg_tree.query(0, left - 1) + 1

            seg_tree.update(i, dp[i])

        return dp[n - 1]

    results = []
    for k in ks:
        T = w - k
        if T >= n:
            results.append("0")
        else:
            result = compute_min_cuts(n, w, x, k)
            results.append(str(result))

