def solution(input_str):
    lines = input_str.strip().split('\n')
    n, b = map(int, lines[0].split())

    items = []
    for line in lines[1:]:
        parts = list(map(int, line.split()))
        c = parts[0]
        d = parts[1]
        x = 0
        if len(parts) > 2:
            x = parts[2]
        items.append((c, d, x))

    # Build tree (0-indexed internally)
    # Node i has parent items[i]['x'] - 1
    adj = [[] for _ in range(n)]
    for i in range(1, n):
        parent = items[i][2] - 1
        adj[parent].append(i)

    # Tree DP: merge subtrees
    # dp[u][j] = min cost to buy j items in subtree rooted at u, with u using coupon
    # no_dp[u][j] = min cost to buy j items in subtree rooted at u, without u using coupon

    # We also need subtree size for pruning
    sz = [1] * n

    def get_sz(u):
        sz[u] = 1
        for v in adj[u]:
            get_sz(v)
            sz[u] += sz[v]
        return sz[u]

    get_sz(0)

    # dp[u] and no_dp[u] are lists where index = number of items from subtree
    # Initialize: only self node for leaf combinations
    memo = {}

    def solve_merge(u):
        # Start with base: just node u
        # no_dp[u] (u without coupon in subtree context)
        no_dp = [float('inf')] * (1 + sz[u])
        no_dp[0] = 0
        no_dp[1] = items[u][0]

        # dp[u] (u must use coupon)
        dp = [float('inf')] * (1 + sz[u])
        dp[1] = items[u][0] - items[u][1]

        for v in adj[u]:
            # Solve child
            child_sz = sz[v]
            merge_v = solve_merge(v)
            vd, vnd = merge_v  # (dp[v], no_dp[v])

            # New sizes: sz[u] increases by child_sz
            sz[u] += child_sz

            new_dp = [float('inf')] * (sz[u] + 1)
            new_no_dp = [float('inf')] * (sz[u] + 1)

            # Merge dp[u] (u with coupon) with child states
            for i in range(len(dp)):
                if dp[i] == float('inf'):
                    continue
                for j in range(len(vd) + 1):
                    if vd[j] == float('inf'):
                        continue
                    # If parent uses coupon, child can use coupon or not
                    # But wait - child without coupon means its own subtree but no parent requirement
                    new_dp[i + j] = min(new_dp[i + j], dp[i] + vd[j])
                for j in range(len(vnd) + 1):
                    if vnd[j] == float('inf'):
                        continue
                    # Parent uses coupon, child doesn't use coupon (child subtree independently)
                    new_dp[i + j] = min(new_dp[i + j], dp[i] + vnd[j])

            # Merge no_dp[u] (u without coupon) with child states
            for i in range(len(no_dp)):
                if no_dp[i] == float('inf'):
                    continue
                for j in range(len(vd) + 1):
                    if vd[j] == float('inf'):
                        continue
                    new_no_dp[i + j] = min(new_no_dp[i + j], no_dp[i] + vd[j])
                for j in range(len(vnd) + 1):
                    if vnd[j] == float('inf'):
                        continue
                    new_no_dp[i + j] = min(new_no_dp[i + j], no_dp[i] + vnd[j])

            dp = new_dp
            no_dp = new_no_dp

        return (dp, no_dp)

    dp_res, no_dp_res = solve_merge(0)

    answer = 0
    for j in range(1, len(dp_res)):
        if dp_res[j] <= b:
            answer = max(answer, j)
    for j in range(1, len(no_dp_res)):
        if no_dp_res[j] <= b:
            answer = max(answer, j)

    return str(answer)

