    # Build containment graph: edge i -> j means string[i] contains string[j]
    graph = [[] for _ in range(n)]

    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            if strings[j] in strings[i]:
                graph[i].append(j)

    # Check for cycles using DFS
    visited = [False] * n
    in_cycle = [False] * n

    def has_cycle(idx):
        if in_cycle[idx]:
            return True
        if visited[idx]:
            return False
        visited[idx] = True
        for neighbor in graph[idx]:
            if has_cycle(neighbor):
                return True
        visited[idx] = False
        return False

    # Simple cycle detection based on containment
    # If i contains j and j contains i (both ways), it's a cycle - skip
    cycle_nodes = set()
    for i in range(n):
        for j in range(n):
            if i != j and strings[j] in strings[i] and strings[i] in strings[j]:
                cycle_nodes.add(i)
                cycle_nodes.add(j)

    # Build filtered graph without cycles
    filtered_graph = [[] for _ in range(n)]
    filtered_in_degree = [0] * n
    for i in range(n):
        for j in graph[i]:
            if i not in cycle_nodes and j not in cycle_nodes:
                filtered_graph[i].append(j)

    # Topological sort using Kahn's algorithm on filtered graph
    in_degree = [0] * n
    for i in range(n):
        for j in filtered_graph[i]:
            in_degree[j] += 1

    queue = deque([i for i in range(n) if in_degree[i] == 0])
    topo_order = []

    while queue:
        idx = queue.popleft()
        topo_order.append(idx)
        for j in filtered_graph[idx]:
            in_degree[j] -= 1
            if in_degree[j] == 0:
                queue.append(j)

    # Handle lexicographic ordering when multiple orders are possible
    # Sort by the actual string for consistent output
    onle_topo_order = sorted(topo_order, key=lambda x: strings[x])

    if len(onle_topo_order) < n:
        # Incomplete topological sort
        return "NO\n"

    # Verify no character conflicts: strings sharing characters must have containment
    for i in range(n):
        for j in range(i + 1, n):
            # Check if they share any character
            common_chars = set(strings[i]) & set(strings[j])
            if len(common_chars) > 0:
                # They share characters - must have containment relationship
                if not (strings[i] in strings[j] or strings[j] in strings[i]):
                    return "NO\n"

    # Build result string in lexicographically sorted topological order
    result_list = []
    visited_topo = set()
    for idx in sorted(topo_order, key=lambda x: strings[x]):
        if idx not in visited_topo:
            result_list.append(strings[idx])
            visited_topo.add(idx)

    result = ''.join(result_list)
    return result + '\n'

